from typing import Dict

from taf.rfrl.procedures.resources.python.l3_call_cloud import make_l3_call_on_each_rmod_cell_if_requested
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError
from taf.rfrl.procedures.cloud.setups_teardowns.testing_env import TestingEnv


def general_siso_auto_cloud_rmods_reset(testing_env: TestingEnv,
                                        throughputs: Dict = None,
                                        ue_network_modes: Dict[str, str] = None):
    """
    Based on:
    QC Test ID: 22218
    QC Test Name: [2.0] General_SiSo_RU_module_reset_from_GUI

    Should report to:
    QC Test ID: 2362
    QC Test Name: General_SiSo_Auto_Cloud_RMODs_Reset

    :param testing_env: testing environment prepared for this test case
    :param throughputs: throughput and deviation values for each Cell identified by its nrCellIdentity for NR Cells,
                        eutranCellId for LTE Cells, wnCelId for WCDMA Cells;
                        i.e.:
                        {'827736065': {'throughput': {'downlink': '100 Mbits/sec',
                                                      'uplink': '15 Mbits/sec},
                                       'deviation': '90%'}}
                        defaults to None (L3 call will not be performed)
    :param ue_network_modes: UE serial numbers paired with desired network modes;
                             i.e. {'HZQN1876AAK90100042': 'NR_only',
                                   'M6AIKN009217SWX': 'LTE_only'}
                             possible UE network modes: 'NR_only', 'LTE_only', 'NR_LTE';
                             when using more than one UE please make sure that modes you choose are either all
                             with '_only' suffix or all are 'NR_LTE' as it is not yet possible to mix those.
                             this param is mandatory for SA+NSA mode;
                             defaults to None (network mode will not be changed on any UE)
    """
    bts = testing_env.btss[0]
    caller = testing_env.caller
    errors = testing_env.errors
    output_dir_path = testing_env.output_dir_path

    for rmod in bts.rmods:
        try:
            _allow_alarms_related_to_resetting_rmod(rmod)
            _reset_rmod_and_check_if_it_was_successful(rmod)
            _wait_for_rmod_to_recover_after_reset(rmod)
            _disallow_alarms_related_to_resetting_rmod(rmod)
            _check_if_other_rmods_were_not_affected(bts, rmod)
            make_l3_call_on_each_rmod_cell_if_requested(rmod=rmod,
                                                        caller=caller,
                                                        throughputs=throughputs,
                                                        ue_network_modes=ue_network_modes,
                                                        logs_path=output_dir_path,
                                                        errors=errors)
        except ResultError as exc:
            errors.add_from_exception(exc=exc)

    errors.check()


def _allow_alarms_related_to_resetting_rmod(rmod):
    rmod.du.allow_alarm(fault_name='No connection to unit',
                        unit_path=rmod.config_dist_name)
    rmod.du.cu.allow_alarm(fault_name='Matching ServedCell not found over F1-C')
    rmod.du.allow_alarm(fault_id='4675')


def _reset_rmod_and_check_if_it_was_successful(rmod):
    rmod.reset()
    rmod.cells.check_state_on_all(state='failed',
                                  timeout=60)
    rmod.check_state(state='not_installed')


def _wait_for_rmod_to_recover_after_reset(rmod):
    rmod.cells.check_state_on_all(state='online',
                                  timeout=600,
                                  interval=5)
    rmod.check_state(state='online',
                     timeout=60)


def _disallow_alarms_related_to_resetting_rmod(rmod):
    rmod.du.disallow_alarm(fault_name='No connection to unit',
                           unit_path=rmod.config_dist_name)
    rmod.du.cu.disallow_alarm(fault_name='Matching ServedCell not found over F1-C')
    rmod.du.disallow_alarm(fault_id='4675')


def _check_if_other_rmods_were_not_affected(bts, tested_rmod):
    for rmod in bts.rmods:
        if rmod is not tested_rmod:
            rmod.cells.check_state_on_all(state='online')
            rmod.check_state(state='online')
